    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def next_token():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = next_token()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = next_token()
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                # truncate toward zero
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                val = q
        return val

    def parse_factor():
        neg = False
        while peek() == '-':
            next_token()
            neg = not neg
        val = parse_atom()
        return -val if neg else val

